INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1429077, 182763, 38634, '<td valign="top">amazing color and clarity</td>', 'amazing color and clarity', '2005-06-02 12:43:48.000000', NULL, 1),
(1429085, 183302, 23478, '<td valign="top">Nice colors and lighting.</td>', 'Nice colors and lighting.', '2005-06-02 12:47:16.000000', NULL, 1),
(1429104, 183275, 27789, '<td valign="top">i like the addition of the boat in the shot, and there''s a simplicity to the composition that is nice.  I would suggest cropping some of the bottom off because the ground is rather dull and gray, in contrast to the richness of the water, boat, trees, and sky.</td>', 'i like the addition of the boat in the shot, and there''s a simplicity to the composition that is nice.  I would suggest cropping some of the bottom off because the ground is rather dull and gray, in contrast to the richness of the water, boat, trees, and sky.', '2005-06-02 12:57:27.000000', NULL, 1),
(1429111, 183181, 5822, '<td valign="top">Love the silhouettes and the very striking colors. Wonderful job.</td>', 'Love the silhouettes and the very striking colors. Wonderful job.', '2005-06-02 13:04:33.000000', NULL, 1),
(1429123, 182965, 5822, '<td valign="top">I love the color and detail of textures. Very interesting composition as well. Only fault I can find is the cropping out of the wing and body. Still giving high mark.</td>', 'I love the color and detail of textures. Very interesting composition as well. Only fault I can find is the cropping out of the wing and body. Still giving high mark.', '2005-06-02 13:08:54.000000', NULL, 1),
(1429133, 183080, 5822, '<td valign="top">Excellent use of DOF.  I love the soft look of the meadow plants and very wise to make this image B&amp;W. Very well done.</td>', 'Excellent use of DOF.  I love the soft look of the meadow plants and very wise to make this image B&W. Very well done.', '2005-06-02 13:13:06.000000', NULL, 1),
(1429175, 183207, 5822, '<td valign="top">Compositionally, I would have preferred a more blurred background from a narrow DOF, and also, you should have moved the budding bloom in the lower left from blocking the petal.  Color is very good.</td>', 'Compositionally, I would have preferred a more blurred background from a narrow DOF, and also, you should have moved the budding bloom in the lower left from blocking the petal.  Color is very good.', '2005-06-02 13:36:23.000000', NULL, 1),
(1429191, 183340, 38685, '<td valign="top">Wow!</td>', 'Wow!', '2005-06-02 13:44:37.000000', NULL, 1),
(1429196, 183302, 5822, '<td valign="top">Outstanding lighting and color. Focus is excellent and textures of the cloth and your model''s skin adds to the impact of this photo.  A ribbon is certainly coming your way. Great job!</td>', 'Outstanding lighting and color. Focus is excellent and textures of the cloth and your model''s skin adds to the impact of this photo.  A ribbon is certainly coming your way. Great job!', '2005-06-02 13:46:16.000000', NULL, 1),
(1429202, 183030, 5822, '<td valign="top">Exquisite abstract! Love it, very well done.</td>', 'Exquisite abstract! Love it, very well done.', '2005-06-02 13:49:33.000000', NULL, 1),
