(1429433, 182959, 31399, '<td valign="top">beautiful as your stuff always is :-)  10</td>', 'beautiful as your stuff always is :-)  10', '2005-06-02 15:49:07.000000', NULL, 1),
(1429434, 182543, 32997, '<td valign="top">Dof really works here..really like this shot.</td>', 'Dof really works here..really like this shot.', '2005-06-02 15:49:57.000000', NULL, 1),
