(1432018, 182983, 6668, '<td valign="top">The yellow in the flower seems a bit oversaturated in my opinion.</td>', 'The yellow in the flower seems a bit oversaturated in my opinion.', '2005-06-03 19:44:27.000000', NULL, 1),
(1432019, 181752, 6668, '<td valign="top">This really is beautiful and would make a lovely print, the colors are outstanding, what an excellent capture!</td>', 'This really is beautiful and would make a lovely print, the colors are outstanding, what an excellent capture!', '2005-06-03 19:45:19.000000', NULL, 1),
(1432021, 182211, 6519, '<td valign="top">I hate that stuff, but will make sure NOT to let that influence my opinion of your photograph. Great lighting and you certainly paid attention to detail. It''s good that the very bottom of the glass is visible again, puts things in their proper perspective.</td>', 'I hate that stuff, but will make sure NOT to let that influence my opinion of your photograph. Great lighting and you certainly paid attention to detail. It''s good that the very bottom of the glass is visible again, puts things in their proper perspective.', '2005-06-03 19:46:23.000000', NULL, 1),
