(1433693, 181725, 23478, '<td valign="top">Very nice.... the subtle yellows and pinks are great.</td>', 'Very nice.... the subtle yellows and pinks are great.', '2005-06-04 23:31:32.000000', NULL, 1),
(1433694, 182765, 19982, '<td valign="top">Above all else, the eyes must be in focus.</td>', 'Above all else, the eyes must be in focus.', '2005-06-04 23:31:42.000000', NULL, 1),
