(1433696, 182174, 23478, '<td valign="top">Stunning clouds.</td>', 'Stunning clouds.', '2005-06-04 23:32:36.000000', NULL, 1),
(1433697, 182813, 19982, '<td valign="top">Careful with the USM on water...  it makes the water look hard and unnatural.   What I usually do is apply USM to the entire image, then use the history brush to paint back the water.</td>', 'Careful with the USM on water...  it makes the water look hard and unnatural.   What I usually do is apply USM to the entire image, then use the history brush to paint back the water.', '2005-06-04 23:33:01.000000', NULL, 1),
(1433698, 182903, 23478, '<td valign="top">What a beautiful baby!</td>', 'What a beautiful baby!', '2005-06-04 23:33:04.000000', NULL, 1),
(1433699, 181752, 19982, '<td valign="top">Nice colors!  And perfect focus on the butterfly.</td>', 'Nice colors!  And perfect focus on the butterfly.', '2005-06-04 23:33:49.000000', NULL, 1),
(1433705, 182855, 30490, '<td valign="top">nice photo of a great cat!  I think you need a little more light on the right side of the photo. clear and crisp 5</td>', 'nice photo of a great cat!  I think you need a little more light on the right side of the photo. clear and crisp 5', '2005-06-04 23:40:05.000000', NULL, 1);
